SELECT f.kind || ' · ' || f.name FROM code_fact f WHERE f.project_id = $1 AND f.kind IN ('contract-file', 'contract-body', 'contract-head', 'contract-mark', 'contract-schema', 'requirement-op', 'requirement-in-contract') UNION ALL SELECT 'датчик «contract-file» ' || fact_gap($1, 'contract-file') || ': есть ли HTTP-контракт — не установлено' WHERE NOT fact_fresh($1, 'contract-file')
